package com.govweb.security;
import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import java.nio.charset.StandardCharsets; import java.util.Date; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service;
@Service public class JwtService { private final String secret; public JwtService(@Value("${app.jwt.secret:govweb-development-secret-key-change-me-2026}") String secret){this.secret=secret;} public String create(String email,String role){var now=new Date(); return Jwts.builder().subject(email).claim("role",role).issuedAt(now).expiration(new Date(now.getTime()+86400000)).signWith(Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8))).compact();} public Claims parse(String token){return Jwts.parser().verifyWith(Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8))).build().parseSignedClaims(token).getPayload();} }
